#include "EquipmentScene.hpp"

#include <cmath>
#include <cstring>
#include <optional>
#include <string>

#if defined(__ANDROID__)
#include "EmbeddedAssets.hpp" // generated by CMake: Equipment.json and the meshes, as text inside the app
#endif
#include "Raycast.hpp"
#include "Renderer.hpp"
#include "ObjLoader.hpp"
#include "PlatformLog.hpp"

// The one scene. A function-local static: built on first use.
EquipmentScene& EquipmentScene::Get()
{
    static EquipmentScene instance;
    return instance;
}

// Android has no loose files to open, so CMake bakes the .obj text into the app (EmbeddedAssets.hpp) and this looks it
// up by the same repo path Equipment.json uses. A linear search is fine: a handful of files, once at start-up.
char const* EquipmentScene::FindAsset(char const* path)
{
#if defined(__ANDROID__)
    for (int i = 0; i < gEmbeddedAssetCount; ++i)
    {
        if (std::strcmp(gEmbeddedAssets[i].path, path) == 0)
        {
            return gEmbeddedAssets[i].text;
        }
    }
#else
    (void)path; // desktop has no embedded assets
#endif
    return nullptr;
}

// Equipment has no colour in the data yet, so each piece gets one from a small palette.
Vector3D EquipmentScene::ColorFor(std::size_t index)
{
    static Vector3D const palette[3] = {Vector3D{0.92f, 0.88f, 0.70f}, Vector3D{0.70f, 0.72f, 0.78f},
                                        Vector3D{0.60f, 0.40f, 0.24f}};
    return palette[index % 3];
}

// The debug square: 12 cm wide, lying flat just above the plane (+y is the plane's normal).
MeshData EquipmentScene::MakeMarkerMesh()
{
    float const    half = 0.06f;
    float const    lift = 0.003f;
    Vector3D const up   = {0.0f, 1.0f, 0.0f};
    MeshData       marker;
    marker.vertices = {Vertex{Vector3D{-half, lift, -half}, up, Vector2D{0.0f, 0.0f}},
                       Vertex{Vector3D{half, lift, -half}, up, Vector2D{1.0f, 0.0f}},
                       Vertex{Vector3D{half, lift, half}, up, Vector2D{1.0f, 1.0f}},
                       Vertex{Vector3D{-half, lift, half}, up, Vector2D{0.0f, 1.0f}}};
    marker.indices  = {0, 1, 2, 0, 2, 3};
    return marker;
}

// Reads every piece's mesh, measures its bounding box (for tap picking), precomputes its place on the anchor, and hands
// all meshes to the Renderer. Stops at the first missing or broken mesh so the log names the exact file.
bool EquipmentScene::Init(EquipmentLibrary loadedLibrary)
{
    if (loaded)
    {
        return true; // a new GL context only needs new GPU handles, and the Renderer remakes those itself
    }

    if (loadedLibrary.items.empty())
    {
        LOGE("No equipment to show: no ECS entity has both MeshRef and Transform3D");
        return false;
    }

    std::vector<MeshData> loadedMeshes;
    for (EquipmentDef& def : loadedLibrary.items)
    {
        char const* text = FindAsset(def.meshPath.c_str());
        if (text == nullptr)
        {
            LOGE("Equipment '%s': mesh '%s' is not embedded in the app", def.id.c_str(), def.meshPath.c_str());
            return false;
        }
        std::optional<MeshData> mesh = ParseObj(text);
        if (!mesh)
        {
            LOGE("Equipment '%s': cannot read mesh '%s'", def.id.c_str(), def.meshPath.c_str());
            return false;
        }

        def.localBounds = Collider{};
        for (Vertex const& vertex : mesh->vertices)
        {
            def.localBounds.Include(vertex.pos);
        }
        loadedMeshes.push_back(std::move(*mesh));
    }

    library = std::move(loadedLibrary);
    localModels.clear();
    for (EquipmentDef const& def : library.items)
    {
        // Row vectors, leftmost applies first: scale, turn, then move to its spot on the anchor.
        localModels.push_back(
            Matrix4x4::SRT(Vector3D{def.scale, def.scale, def.scale}, Vector3D{0.0f, def.yawDeg, 0.0f}, def.position));
    }
    loadedMeshes.push_back(MakeMarkerMesh()); // always last: its index is library.items.size()
    meshes = std::move(loadedMeshes);
    Renderer::Get().SetMeshes(meshes);
    loaded = true;
    LOGI("Equipment loaded: %zu pieces", library.items.size());
    return true;
}

// Tap picking: turn the tap into a ray through the camera (Raycast.hpp), test it against every piece's box in world
// space (Collider.hpp), and select the nearest hit. A tap on empty space clears the selection.
void EquipmentScene::Update(float /*dt*/, InputSnapshot const& input, bool tracking, Matrix4x4 const& view,
                            Matrix4x4 const& projection, int viewportW, int viewportH)
{
    if (!loaded || !tracking)
    {
        return; // nothing to place, or no trustworthy camera: nothing to place, nothing to pick
    }

    if (!placed || !stationShown)
    {
        return; // still scanning, or hidden: the pieces can be picked only while they are on screen
    }

    if (input.Tapped)
    {
        Raycast const ray = ScreenPointToRay(input.TapX, input.TapY, viewportW, viewportH, view, projection);

        // Nearest piece whose world box the ray enters (Collider does the box test, Raycast made the ray).
        std::optional<std::size_t> nearest;
        float                      nearestDistance = 0.0f;
        for (std::size_t i = 0; i < library.items.size(); ++i)
        {
            float distance = 0.0f;
            if (library.items[i].localBounds.Transformed(models[i]).IntersectsRay(ray, distance) &&
                (!nearest || distance < nearestDistance))
            {
                nearest         = i;
                nearestDistance = distance;
            }
        }
        selected = nearest;
        if (nearest)
        {
            LOGI("Tap (%.0f, %.0f) selected %s", input.TapX, input.TapY, library.items[*nearest].id.c_str());
        }
        else
        {
            LOGI("Tap (%.0f, %.0f) hit nothing", input.TapX, input.TapY);
        }
    }
}

void EquipmentScene::SetPlanes(std::vector<Matrix4x4> const& poses, std::vector<Vector2D> const& extents)
{
    // The unit square mesh is 12 cm wide, so it is stretched to the plane's size first, then moved onto the plane.
    float const markerWidth = 0.12f;
    planeModels.clear();
    for (std::size_t i = 0; i < poses.size() && i < extents.size(); ++i)
    {
        planeModels.push_back(Matrix4x4::Scale(extents[i].x / markerWidth, 1.0f, extents[i].y / markerWidth) *
                              poses[i]);
    }
}

// Stores the debug square's state and pose for the next Draw.
void EquipmentScene::SetMarker(int state, Matrix4x4 const& pose)
{
    markerState = state;
    markerPose  = pose;
}

void EquipmentScene::SetAnchorPose(Matrix4x4 const& pose)
{
    anchorPose = pose;
    placed     = true; // the first call is what places the pieces: before it, the scene is "scanning" and draws nothing
    RefreshModels();   // every call after that follows the anchor, so picking and drawing use the corrected spot
}

// Recomputes every piece's world matrix from the latest anchor pose. Called on every anchor update, so picking (Update)
// and drawing (Draw) always use the same, corrected spot.
void EquipmentScene::RefreshModels()
{
    models.clear();
    models.reserve(localModels.size());
    for (Matrix4x4 const& local : localModels)
    {
        models.push_back(local * anchorPose); // local -> anchor-local -> ARCore world
    }
}

// Builds this frame's draw list (planes while scanning, the pieces once placed and trusted, the debug square) and hands
// it to the Renderer in one call. Order matters only for see-through items: they are listed after what they cover.
void EquipmentScene::Draw(Matrix4x4 const& view, Matrix4x4 const& projection)
{
    if (!loaded)
    {
        return;
    }

    // Selection becomes a plain tint colour here. The Renderer only knows colours and matrices.
    std::vector<Renderer::MeshDraw> draws;
    draws.reserve(library.items.size() + 1);

    // The detected planes first, as see-through rectangles: the pieces and the debug square are drawn over them.
    // Only while scanning: once the station is placed they would just cover it.
    if (!placed && meshes.size() > library.items.size())
    {
        for (Matrix4x4 const& planeModel : planeModels)
        {
            Renderer::MeshDraw plane;
            plane.meshIndex = library.items.size();
            plane.model     = planeModel;
            plane.color     = Vector3D{0.1f, 0.75f, 0.85f}; // blue-green
            plane.alpha     = 0.35f;
            draws.push_back(plane);
        }
    }

    if (placed && stationShown)
    {
        for (std::size_t i = 0; i < library.items.size() && i < meshes.size(); ++i)
        {
            Renderer::MeshDraw draw;
            draw.meshIndex  = i;
            draw.model      = models[i];
            draw.color      = ColorFor(i);
            draw.tint       = Vector3D{1.0f, 0.85f, 0.2f}; // yellow
            draw.tintAmount = (selected && *selected == i) ? 0.45f : 0.0f;
            draws.push_back(draw);
        }
    }

    // The debug square: red = a plane the code won't use, yellow = a good plane (holding steady), green = the anchor.
    if (markerState != 0 && (!placed || stationShown) && meshes.size() > library.items.size())
    {
        Renderer::MeshDraw marker;
        marker.meshIndex = library.items.size();
        marker.model     = Matrix4x4::Translate(0.0f, 0.004f, 0.0f) * markerPose; // just above a drawn plane
        marker.color     = markerState == 1   ? Vector3D{0.9f, 0.2f, 0.2f}
                           : markerState == 2 ? Vector3D{0.95f, 0.8f, 0.1f}
                                              : Vector3D{0.2f, 0.8f, 0.3f};
        marker.occludable = false; // a debug aid lying on the surface: depth would half-hide it
        draws.push_back(marker);
    }

    if (draws.empty())
    {
        return;
    }
    Renderer::Get().DrawMeshes(draws, view, projection);
}

void EquipmentScene::DrawLoader(float seconds, int viewportW, int viewportH)
{
    if (!loaded || meshes.size() <= library.items.size())
    {
        return;
    }

    // Straight onto the screen: view and projection are identity, so each model matrix places a dot in screen units
    // (-1..1 across). x is squeezed by the screen's shape so the ring stays round.
    float const aspect      = (viewportW > 0 && viewportH > 0) ? static_cast<float>(viewportW) / viewportH : 1.0f;
    float const markerWidth = 0.12f;  // the square mesh's width
    float const dotSize     = 0.022f; // in screen-height units
    float const radius      = 0.07f;
    int const   dots        = 10;
    float const stepsPerSec = 10.0f;  // the bright dot moves one place every 0.1 s: one turn a second
    float const head        = std::fmod(seconds * stepsPerSec, static_cast<float>(dots));
    float const degToRad    = 3.14159265f / 180.0f;

    std::vector<Renderer::MeshDraw> draws;
    draws.reserve(dots);
    for (int i = 0; i < dots; ++i)
    {
        float const angle = 90.0f - 360.0f * i / dots; // clockwise from the top
        float const age   = std::fmod(head - i + dots, static_cast<float>(dots)) / dots; // 0 = the bright one, then fading
        Renderer::MeshDraw dot;
        dot.meshIndex  = library.items.size();
        dot.model      = Matrix4x4::Scale(dotSize / markerWidth, 1.0f, dotSize / markerWidth) * // square, dot-sized
                    Matrix4x4::RotateX(90.0f) *                                                // flat on the screen
                    Matrix4x4::Translate(radius * std::cos(angle * degToRad), radius * std::sin(angle * degToRad), 0.0f) *
                    Matrix4x4::Scale(1.0f / aspect, 1.0f, 1.0f);
        dot.tint       = Vector3D{1.0f, 1.0f, 1.0f}; // tint 1 = plain white, no lighting
        dot.tintAmount = 1.0f;
        dot.alpha      = 0.15f + 0.7f * (1.0f - age);
        dot.occludable = false; // a screen item: never hidden by the depth picture
        draws.push_back(dot);
    }
    Renderer::Get().DrawMeshes(draws, Matrix4x4{}, Matrix4x4{});
}